eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   getProductById: () => (/* binding */ getProductById),\n/* harmony export */   getRelatedProducts: () => (/* binding */ getRelatedProducts),\n/* harmony export */   products: () => (/* binding */ products)\n/* harmony export */ });\nconst products = [\n    {\n        id: 'thang-homelift',\n        title: 'Thang Homelift',\n        subtitle: 'Giải pháp thang máy cao cấp cho không gian sống',\n        icon: 'home',\n        image: 'https://images.pexels.com/photos/3184418/pexels-photo-3184418.jpeg?auto=compress&cs=tinysrgb&w=1200&q=80',\n        shortDescription: 'Thiết kế sang trọng, tối ưu không gian. Phù hợp với nhà phố, biệt thự với cabin kính toàn phần hoặc inox mờ cao cấp.',\n        fullDescription: `Thang Homelift Hải Phát được thiết kế riêng biệt cho từng không gian sống, mang đến sự tiện nghi và đẳng cấp cho gia đình bạn. Với công nghệ tiên tiến từ các thương hiệu hàng đầu thế giới như Mitsubishi, Otis, Schindler, chúng tôi cam kết mang đến sản phẩm chất lượng cao với vận hành êm ái, an toàn tuyệt đối.\n\nDòng thang Homelift của chúng tôi phù hợp với nhiều kiểu kiến trúc khác nhau - từ nhà phố liền kề, biệt thự cổ điển đến biệt thự hiện đại. Cabin có thể tùy chỉnh với nhiều vật liệu cao cấp: kính cường lực trong suốt, inox mờ, gỗ tự nhiên hay laminate chống trầy xước.`,\n        features: [\n            'Cabin kính cường lực cao cấp',\n            'Cửa mở tự động êm ái',\n            'Hệ thống an toàn đa điểm',\n            'Vận hành siêu êm < 45dB',\n            'Đèn LED tiết kiệm điện',\n            'Màn hình hiển thị tầng số',\n            'Hệ thống báo động tự động',\n            'Chống quá tải thông minh'\n        ],\n        specifications: [\n            {\n                label: 'Tải trọng',\n                value: '250kg - 630kg (3-8 người)'\n            },\n            {\n                label: 'Tốc độ',\n                value: '0.4 - 1.0 m/s'\n            },\n            {\n                label: 'Số tầng',\n                value: 'Tối đa 12 tầng'\n            },\n            {\n                label: 'Kích thước cabin',\n                value: 'Từ 1.0m x 1.2m'\n            },\n            {\n                label: 'Công suất motor',\n                value: '2.2 - 5.5 kW'\n            },\n            {\n                label: 'Điện áp',\n                value: '220V/380V, 50Hz'\n            },\n            {\n                label: 'Bảo hành',\n                value: '18 tháng toàn bộ'\n            },\n            {\n                label: 'Bảo trì',\n                value: 'Miễn phí 2 tháng/lần'\n            }\n        ],\n        benefits: [\n            'Tăng giá trị bất động sản lên 15-20%',\n            'Tiện lợi cho người già và trẻ nhỏ',\n            'Vận chuyển đồ đạc dễ dàng',\n            'Không gian sang trọng, đẳng cấp',\n            'Tiết kiệm thời gian di chuyển',\n            'An toàn với hệ thống đa lớp'\n        ],\n        process: [\n            {\n                step: 1,\n                title: 'Khảo sát & Tư vấn',\n                description: 'Đội ngũ kỹ sư giàu kinh nghiệm sẽ đến khảo sát hiện trạng, đo đạc không gian và tư vấn giải pháp phù hợp nhất.'\n            },\n            {\n                step: 2,\n                title: 'Thiết kế & Báo giá',\n                description: 'Lên bản vẽ kỹ thuật 3D, phối cảnh nội thất và báo giá chi tiết từng hạng mục.'\n            },\n            {\n                step: 3,\n                title: 'Ký hợp đồng & Đặt hàng',\n                description: 'Ký hợp đồng với điều khoản rõ ràng, đặt cọc và tiến hành đặt thiết bị từ nhà sản xuất.'\n            },\n            {\n                step: 4,\n                title: 'Thi công lắp đặt',\n                description: 'Đội ngũ kỹ thuật được đào tạo bài bản thi công lắp đặt theo tiêu chuẩn, đúng tiến độ cam kết.'\n            },\n            {\n                step: 5,\n                title: 'Nghiệm thu & Bàn giao',\n                description: 'Vận hành thử, kiểm tra an toàn, hướng dẫn sử dụng và bàn giao cho khách hàng.'\n            },\n            {\n                step: 6,\n                title: 'Bảo trì & Hậu mãi',\n                description: 'Hỗ trợ kỹ thuật 24/7, bảo trì định kỳ miễn phí và cung cấp phụ tùng chính hãng.'\n            }\n        ],\n        faqs: [\n            {\n                question: 'Nhà tôi diện tích nhỏ, có lắp được thang máy không?',\n                answer: 'Có thể. Chúng tôi có các dòng Homelift mini với kích thước cabin chỉ từ 1.0m x 1.2m, phù hợp với nhà phố nhỏ.'\n            },\n            {\n                question: 'Thời gian lắp đặt mất bao lâu?',\n                answer: 'Từ 7-14 ngày làm việc tùy theo độ phức tạp của công trình và điều kiện hiện trạng.'\n            },\n            {\n                question: 'Thang Homelift tốn nhiều điện không?',\n                answer: 'Không. Thang tiêu thụ khoảng 2-5 kWh/ngày, tương đương chi phí 5,000-12,000 VND/ngày.'\n            },\n            {\n                question: 'Bảo hành như thế nào?',\n                answer: 'Bảo hành 18 tháng toàn bộ thiết bị, bảo trì miễn phí 2 tháng/lần trong thời gian bảo hành, hỗ trợ kỹ thuật 24/7.'\n            }\n        ],\n        relatedProjects: [\n            'villa-ecopark',\n            'house-thao-dien'\n        ]\n    },\n    {\n        id: 'thang-may-tai-khach',\n        title: 'Thang Máy Tải Khách',\n        subtitle: 'Hiệu suất cao cho tòa nhà văn phòng và chung cư',\n        icon: 'building',\n        image: 'https://images.pexels.com/photos/2467285/pexels-photo-2467285.jpeg?auto=compress&cs=tinysrgb&w=1200&q=80',\n        shortDescription: 'Giải pháp lý tưởng cho tòa nhà, văn phòng, bệnh viện, khách sạn. Tải trọng lớn, vận hành êm ái, đáp ứng tiêu chuẩn QCVN và EN 81.',\n        fullDescription: `Thang máy tải khách Hải Phát là giải pháp vận chuyển tối ưu cho các công trình thương mại, văn phòng, chung cư cao tầng với lưu lượng người lớn. Với công nghệ điều khiển nhóm thông minh, hệ thống phân bổ luồng người tự động giúp giảm thời gian chờ đợi và tăng hiệu suất vận hành.\n\nChúng tôi cung cấp các dòng thang từ tốc độ tiêu chuẩn 1.0 m/s đến tốc độ cao 2.5 m/s cho các tòa nhà cao tầng. Thiết kế cabin hiện đại với nhiều lựa chọn nội thất cao cấp, đáp ứng mọi yêu cầu thẩm mỹ khắt khe nhất.`,\n        features: [\n            'Tốc độ vận hành đa dạng',\n            'Hệ thống nhóm thông minh',\n            'Màn hình LCD 10\" - 21\"',\n            'Nội thất gỗ/inox cao cấp',\n            'Hệ thống dự báo tầng',\n            'Chống rung vận hành êm',\n            'Chế độ tiết kiệm điện',\n            'Kết nối BMS tòa nhà'\n        ],\n        specifications: [\n            {\n                label: 'Tải trọng',\n                value: '630kg - 2000kg (8-26 người)'\n            },\n            {\n                label: 'Tốc độ',\n                value: '1.0 - 4.0 m/s'\n            },\n            {\n                label: 'Số tầng',\n                value: 'Tối đa 50 tầng'\n            },\n            {\n                label: 'Kích thước cabin',\n                value: 'Từ 1.4m x 1.6m'\n            },\n            {\n                label: 'Công suất motor',\n                value: '7.5 - 30 kW'\n            },\n            {\n                label: 'Điện áp',\n                value: '380V, 50Hz'\n            },\n            {\n                label: 'Bảo hành',\n                value: '18 tháng thiết bị'\n            },\n            {\n                label: 'Bảo trì',\n                value: '2 tháng/lần trong BH'\n            }\n        ],\n        benefits: [\n            'Tăng năng suất vận chuyển',\n            'Giảm thời gian chờ đợi',\n            'An toàn tuyệt đối cho người dùng',\n            'Tiết kiệm chi phí vận hành',\n            'Dễ dàng tích hợp BMS',\n            'Vận hành bền bỉ 24/7'\n        ],\n        process: [\n            {\n                step: 1,\n                title: 'Tư vấn giải pháp',\n                description: 'Phân tích nhu cầu, lưu lượng người và đặc điểm công trình để đề xuất số lượng và loại thang phù hợp.'\n            },\n            {\n                step: 2,\n                title: 'Thiết kế hệ thống',\n                description: 'Thiết kế bố trí thang máy, giếng thang, máy phòng với bản vẽ chi tiết 2D/3D.'\n            },\n            {\n                step: 3,\n                title: 'Cung cấp thiết bị',\n                description: 'Nhập khẩu thiết bị chính hãng từ các nhà sản xuất uy tín, đầy đủ CO, CQ.'\n            },\n            {\n                step: 4,\n                title: 'Lắp đặt & Vận hành',\n                description: 'Lắp đặt theo tiêu chuẩn QCVN 06:2022, vận hành thử và hiệu chỉnh trước khi bàn giao.'\n            },\n            {\n                step: 5,\n                title: 'Đào tạo & Bàn giao',\n                description: 'Đào tạo vận hành cho nhân viên tòa nhà, cung cấp tài liệu và chứng nhận kiểm định.'\n            },\n            {\n                step: 6,\n                title: 'Bảo trì chuyên nghiệp',\n                description: 'Hợp đồng bảo trì định kỳ, cung cấp phụ tùng thay thế, hỗ trợ khẩn cấp 24/7.'\n            }\n        ],\n        faqs: [\n            {\n                question: 'Bao nhiêu thang máy cho tòa nhà 20 tầng?',\n                answer: 'Phụ thuộc vào mật độ người. Trung bình cần 1 thang cho mỗi 50-70 người, tối thiểu 2 thang cho tòa nhà trên 10 tầng.'\n            },\n            {\n                question: 'Thang máy tốc độ cao có an toàn không?',\n                answer: 'Có. Thang máy tốc độ cao được trang bị hệ thống phanh đa lớp, bộ điều tốc độc lập và cảm biến an toàn đầy đủ theo chuẩn EN 81.'\n            },\n            {\n                question: 'Chi phí bảo trì hàng năm khoảng bao nhiêu?',\n                answer: 'Chi phí bảo trì khoảng 8-15 triệu/tháng cho một thang máy, tùy vào số lượng tầng và điều kiện vận hành.'\n            },\n            {\n                question: 'Có tích hợp được với hệ thống BMS không?',\n                answer: 'Có. Thang máy của chúng tôi hỗ trợ giao thức giao tiếp chuẩn, dễ dàng tích hợp với hệ thống quản lý tòa nhà.'\n            }\n        ],\n        relatedProjects: [\n            'landmark-office',\n            'vinmec-times-city'\n        ]\n    },\n    {\n        id: 'thang-may-tai-hang',\n        title: 'Thang Máy Tải Hàng',\n        subtitle: 'Giải pháp vận chuyển hàng hóa công nghiệp',\n        icon: 'truck',\n        image: 'https://images.pexels.com/photos/3557590/pexels-photo-3557590.jpeg?auto=compress&cs=tinysrgb&w=1200&q=80',\n        shortDescription: 'Thang máy chuyên dụng cho nhà kho, nhà máy sản xuất, bệnh viện với tải trọng lớn và sàn cabin chịu lực cao.',\n        fullDescription: `Thang máy tải hàng Hải Phát được thiết kế chuyên biệt cho các nhu cầu vận chuyển hàng hóa trong nhà kho, nhà xưởng, bệnh viện. Với sàn cabin bằng thép chịu lực hoặc gạch granit dày, hệ thống cửa chắn gờ chắc chắn, tải trọng từ 1000kg đến 5000kg.\n\nDòng thang tải hàng có thể tùy chỉnh theo nhu cầu đặc biệt: thang chở xe đẩy, thang tải ô tô, thang chuyên dụng cho bệnh viện với kích thước cabin lớn để vận chuyển giường bệnh.`,\n        features: [\n            'Sàn cabin chịu lực cao',\n            'Cửa chắn gờ 2 lớp',\n            'Tải trọng lên đến 5000kg',\n            'Điều khiển từ cabin',\n            'Hệ thống cân bằng tự động',\n            'Chống rung êm ái',\n            'An toàn quá tải',\n            'Dễ vệ sinh sàn'\n        ],\n        specifications: [\n            {\n                label: 'Tải trọng',\n                value: '1000kg - 5000kg'\n            },\n            {\n                label: 'Tốc độ',\n                value: '0.25 - 1.0 m/s'\n            },\n            {\n                label: 'Kích thước cabin',\n                value: 'Tùy chỉnh theo nhu cầu'\n            },\n            {\n                label: 'Sàn cabin',\n                value: 'Thép / Gạch granit dày'\n            },\n            {\n                label: 'Cửa',\n                value: 'Cửa kéo / Cửa mở tay'\n            },\n            {\n                label: 'Động cơ',\n                value: 'AC 3 pha, 380V'\n            },\n            {\n                label: 'Bảo hành',\n                value: '3 năm thiết bị'\n            },\n            {\n                label: 'Bảo trì',\n                value: '2 tháng/lần trong BH'\n            }\n        ],\n        benefits: [\n            'Vận chuyển hàng nặng dễ dàng',\n            'Tăng năng suất kho bãi',\n            'An toàn cho người và hàng',\n            'Tiết kiệm chi phí nhân công',\n            'Vận hành bền bỉ 24/7',\n            'Dễ dàng tích hợp hệ thống'\n        ],\n        process: [\n            {\n                step: 1,\n                title: 'Đánh giá nhu cầu',\n                description: 'Xác định tải trọng, kích thước hàng hóa và tần suất vận chuyển để thiết kế phù hợp.'\n            },\n            {\n                step: 2,\n                title: 'Thiết kế kỹ thuật',\n                description: 'Thiết kế kết cấu giếng thang, máy phòng và cabin theo tiêu chuẩn chịu lực.'\n            },\n            {\n                step: 3,\n                title: 'Chế tạo đặc biệt',\n                description: 'Chế tạo cabin, khung đối trọng và hệ thống cửa chịu lực cao.'\n            },\n            {\n                step: 4,\n                title: 'Lắp đặt & Kiểm tra',\n                description: 'Lắp đặt hệ thống, kiểm tra tải trọng và vận hành thử nghiệm.'\n            },\n            {\n                step: 5,\n                title: 'Đào tạo vận hành',\n                description: 'Đào tạo vận hành an toàn, quy trình load hàng và xử lý sự cố.'\n            },\n            {\n                step: 6,\n                title: 'Bảo trì định kỳ',\n                description: 'Bảo trì định kỳ thay thế các chi tiết chịu lực, đảm bảo vận hành an toàn.'\n            }\n        ],\n        faqs: [\n            {\n                question: 'Thang tải hàng khác thang tải khách thế nào?',\n                answer: 'Thang tải hàng có sàn chịu lực cao, tốc độ chậm hơn, cửa chắn gờ và không có yêu cầu thẩm mỹ nội thất.'\n            },\n            {\n                question: 'Có chở được xe tải không?',\n                answer: 'Có dòng thang tải ô tô chuyên dụng với tải trọng 3000-5000kg và kích thước cabin đủ cho xe bán tải.'\n            },\n            {\n                question: 'Bảo trì thang tải hàng khác gì thang thường?',\n                answer: 'Bảo trì tập trung vào các chi tiết chịu lực: cáp, rulo, ray dẫn hướng, thay thế định kỳ theo khuyến nghị.'\n            },\n            {\n                question: 'Thang tải hàng chạy 24/7 được không?',\n                answer: 'Có với dòng công nghiệp. Thang được thiết kế vận hành liên tục với hệ thống làm mát motor riêng.'\n            }\n        ],\n        relatedProjects: [\n            'vinmec-times-city'\n        ]\n    },\n    {\n        id: 'thang-may-quan-sat',\n        title: 'Thang Máy Quan Sát',\n        subtitle: 'Thang máy kính toàn cảnh cho kiến trúc nổi bật',\n        icon: 'eye',\n        image: 'https://images.pexels.com/photos/32260201/pexels-photo-32260201.jpeg?auto=compress&cs=tinysrgb&w=1200&q=80',\n        shortDescription: 'Thang máy kính toàn cảnh lắp ngoài công trình, mang lại điểm nhấn kiến trúc độc đáo và trải nghiệm thị giác ấn tượng cho người sử dụng.',\n        fullDescription: `Thang máy quan sát Hải Phát được thiết kế với cabin kính toàn cảnh, lắp đặt bên ngoài các công trình cao tầng như khách sạn, trung tâm thương mại, tòa nhà văn phòng và các công trình biểu tượng. Với tầm nhìn 360 độ, thang máy quan sát không chỉ là phương tiện di chuyển mà còn là một điểm nhấn kiến trúc độc đáo, nâng tầm giá trị thẩm mỹ cho công trình.\n\nCabin kính được chế tạo từ kính cường lực an toàn đa lớp, chịu được chênh lệch áp suất và điều kiện thời tiết khắc nghiệt. Hệ thống dẫn hướng và đối trọng được bố trí khéo léo để không cản trở tầm nhìn, kết hợp với hệ thống chiếu sáng LED tạo hiệu ứng ánh sáng ấn tượng về đêm.`,\n        features: [\n            'Cabin kính cường lực toàn cảnh 360°',\n            'Kính an toàn đa lớp dày 12mm+',\n            'Hệ thống chiếu sáng LED trang trí',\n            'Đối trọng ẩn không cản tầm nhìn',\n            'Vận hành êm ái, chống rung',\n            'Chống tia UV, cách nhiệt',\n            'Thiết kế chịu điều kiện thời tiết',\n            'Hiệu ứng ánh sáng ban đêm'\n        ],\n        specifications: [\n            {\n                label: 'Tải trọng',\n                value: '630kg - 1600kg (8-21 người)'\n            },\n            {\n                label: 'Tốc độ',\n                value: '1.0 - 2.5 m/s'\n            },\n            {\n                label: 'Số tầng',\n                value: 'Tối đa 40 tầng'\n            },\n            {\n                label: 'Kính cabin',\n                value: 'Kính cường lực dày 12-19mm'\n            },\n            {\n                label: 'Kiểu lắp',\n                value: 'Ngoài công trình / Trong atrium'\n            },\n            {\n                label: 'Điện áp',\n                value: '380V, 50Hz'\n            },\n            {\n                label: 'Bảo hành',\n                value: '18 tháng toàn bộ'\n            },\n            {\n                label: 'Bảo trì',\n                value: '2 tháng/lần trong BH'\n            }\n        ],\n        benefits: [\n            'Tăng giá trị thẩm mỹ công trình',\n            'Điểm nhấn kiến trúc độc đáo',\n            'Trải nghiệm thị giác ấn tượng',\n            'Thu hút khách hàng, tăng doanh thu',\n            'Tối ưu ánh sáng tự nhiên',\n            'Nâng tầm thương hiệu tòa nhà'\n        ],\n        process: [\n            {\n                step: 1,\n                title: 'Khảo sát kiến trúc',\n                description: 'Đánh giá kết cấu công trình, vị trí lắp đặt và phong cách kiến trúc để đề xuất giải pháp phù hợp.'\n            },\n            {\n                step: 2,\n                title: 'Thiết kế phối cảnh',\n                description: 'Thiết kế 3D phối cảnh cabin và vị trí lắp đặt, đảm bảo hài hòa với kiến trúc tổng thể.'\n            },\n            {\n                step: 3,\n                title: 'Chế tạo kính cabin',\n                description: 'Chế tạo cabin kính cường lực theo thiết kế riêng, kiểm tra chất lượng kính đa lớp.'\n            },\n            {\n                step: 4,\n                title: 'Lắp đặt kết cấu',\n                description: 'Lắp đặt khung giá, ray dẫn hướng và hệ thống đối trọng ẩn, đảm bảo không cản trở tầm nhìn.'\n            },\n            {\n                step: 5,\n                title: 'Lắp cabin & Hiệu chỉnh',\n                description: 'Lắp cabin kính, hệ thống chiếu sáng LED, vận hành thử và hiệu chỉnh độ êm.'\n            },\n            {\n                step: 6,\n                title: 'Bàn giao & Bảo trì',\n                description: 'Nghiệm thu, bàn giao và ký hợp đồng bảo trì định kỳ, hỗ trợ kỹ thuật 24/7.'\n            }\n        ],\n        faqs: [\n            {\n                question: 'Thang kính có an toàn khi gặp sự cố không?',\n                answer: 'Có. Kính cường lực đa lớp chịu lực cao, không vỡ thành mảnh nhọn. Thang còn có hệ thống phanh khẩn cấp và bộ điều tốc độc lập.'\n            },\n            {\n                question: 'Thang quan sát lắp ngoài có bị ảnh hưởng thời tiết?',\n                answer: 'Không. Kính và khung được thiết kế chịu điều kiện thời tiết khắc nghiệt, chống tia UV, cách nhiệt và chống ăn mòn.'\n            },\n            {\n                question: 'Có lắp được cho tòa nhà đang hoạt động không?',\n                answer: 'Có. Chúng tôi có phương án lắp ngoài công trình không ảnh hưởng đến hoạt động bên trong, thi công nhanh chóng.'\n            },\n            {\n                question: 'Bảo trì thang kính có phức tạp hơn không?',\n                answer: 'Hơi. Ngoài bảo trì tiêu chuẩn, cần vệ sinh kính định kỳ và kiểm tra độ kín khít, nhưng chi phí không chênh lệch nhiều.'\n            }\n        ],\n        relatedProjects: [\n            'sheraton-da-nang',\n            'landmark-office'\n        ]\n    },\n    {\n        id: 'thang-may-benh-vien',\n        title: 'Thang Máy Bệnh Viện',\n        subtitle: 'Thang máy y tế chuyên dụng cho giường bệnh và băng ca',\n        icon: 'heart-pulse',\n        image: 'https://images.pexels.com/photos/263402/pexels-photo-263402.jpeg?auto=compress&cs=tinysrgb&w=1200&q=80',\n        shortDescription: 'Thang máy y tế chuyên dụng với cabin rộng, sàn chịu lực cao, vận chuyển giường bệnh, băng ca và thiết bị y tế an toàn, êm ái.',\n        fullDescription: `Thang máy bệnh viện Hải Phát được thiết kế chuyên biệt cho các cơ sở y tế như bệnh viện, phòng khám, trung tâm chăm sóc sức khỏe. Với cabin rộng rãi để vận chuyển giường bệnh, băng ca, xe lăn và thiết bị y tế cồng kềnh, sàn cabin chịu lực cao và vận hành êm ái đặc biệt để đảm bảo sự thoải mái cho bệnh nhân.\n\nThang máy bệnh viện tuân thủ các tiêu chuẩn y tế khắt khe: hệ thống cửa mở rộng để giường bệnh ra vào dễ dàng, chế độ vận hành êm ái đặc biệt giảm tối đa rung động, hệ thống ưu tiên cho ca khẩn cấp, và khả năng tích hợp với hệ thống điều hành trung tâm của bệnh viện.`,\n        features: [\n            'Cabin rộng cho giường bệnh & băng ca',\n            'Cửa mở rộng êm ái',\n            'Sàn chịu lực cao, chống trượt',\n            'Vận hành siêu êm cho bệnh nhân',\n            'Chế độ ưu tiên ca khẩn cấp',\n            'Hệ thống khử khuẩn UV (tùy chọn)',\n            'Bảng điều khiển chống khuẩn',\n            'Tích hợp hệ thống điều hành bệnh viện'\n        ],\n        specifications: [\n            {\n                label: 'Tải trọng',\n                value: '1000kg - 2500kg'\n            },\n            {\n                label: 'Tốc độ',\n                value: '0.5 - 1.6 m/s'\n            },\n            {\n                label: 'Kích thước cabin',\n                value: 'Từ 1.4m x 2.4m'\n            },\n            {\n                label: 'Cửa',\n                value: 'Mở tự động 2 cánh rộng'\n            },\n            {\n                label: 'Sàn cabin',\n                value: 'Gạch chống trượt y tế'\n            },\n            {\n                label: 'Điện áp',\n                value: '380V, 50Hz + UPS dự phòng'\n            },\n            {\n                label: 'Bảo hành',\n                value: '18 tháng thiết bị'\n            },\n            {\n                label: 'Bảo trì',\n                value: '2 tháng/lần trong BH'\n            }\n        ],\n        benefits: [\n            'Vận chuyển giường bệnh an toàn',\n            'Ưu tiên ca khẩn cấp kịp thời',\n            'Bệnh nhân thoải mái, ít rung động',\n            'Vệ sinh, chống khuẩn dễ dàng',\n            'Vận hành liên tục 24/7',\n            'Đáp ứng tiêu chuẩn y tế'\n        ],\n        process: [\n            {\n                step: 1,\n                title: 'Khảo sát cơ sở y tế',\n                description: 'Đánh giá nhu cầu vận chuyển, kích thước giường bệnh, luồng di chuyển và quy trình khẩn cấp của bệnh viện.'\n            },\n            {\n                step: 2,\n                title: 'Thiết kế chuyên biệt',\n                description: 'Thiết kế cabin rộng, cửa mở rộng, sàn chịu lực và hệ thống ưu tiên ca khẩn cấp theo tiêu chuẩn y tế.'\n            },\n            {\n                step: 3,\n                title: 'Cung cấp thiết bị',\n                description: 'Nhập khẩu thiết bị chính hãng với đầy đủ CO/CQ, đáp ứng tiêu chuẩn y tế quốc tế.'\n            },\n            {\n                step: 4,\n                title: 'Lắp đặt & Tích hợp',\n                description: 'Lắp đặt theo tiến độ không ảnh hưởng hoạt động bệnh viện, tích hợp hệ thống điều hành trung tâm.'\n            },\n            {\n                step: 5,\n                title: 'Vận hành thử & Đào tạo',\n                description: 'Vận hành thử với giường bệnh, đào tạo nhân viên y tế vận hành và xử lý tình huống khẩn cấp.'\n            },\n            {\n                step: 6,\n                title: 'Bảo trì chuyên nghiệp',\n                description: 'Bảo trì định kỳ với đội ngũ túc trực 24/7, phản ứng sự cố trong vòng 1 giờ cho cơ sở y tế.'\n            }\n        ],\n        faqs: [\n            {\n                question: 'Thang bệnh viện khác thang tải khách thế nào?',\n                answer: 'Cabin rộng hơn để chở giường bệnh, cửa mở rộng, sàn chịu lực cao, vận hành êm ái hơn và có chế độ ưu tiên ca khẩn cấp.'\n            },\n            {\n                question: 'Có vận chuyển được giường ICU không?',\n                answer: 'Có. Cabin được thiết kế rộng đủ cho giường ICU cùng thiết bị y tế đi kèm, với tải trọng từ 1600kg trở lên.'\n            },\n            {\n                question: 'Thang có hoạt động khi mất điện không?',\n                answer: 'Có. Hệ thống UPS dự phòng và phát điện dự phòng đảm bảo thang vận hành liên tục trong sự cố mất điện.'\n            },\n            {\n                question: 'Thời gian phản ứng sự cố là bao lâu?',\n                answer: 'Với cơ sở y tế, chúng tôi cam kết phản ứng trong vòng 1 giờ tại nội thành và 2 giờ tại các tỉnh lân cận.'\n            }\n        ],\n        relatedProjects: [\n            'vinmec-times-city'\n        ]\n    }\n];\nfunction getProductById(id) {\n    return products.find((p)=>p.id === id);\n}\nfunction getRelatedProducts(currentId, limit = 3) {\n    return products.filter((p)=>p.id !== currentId).slice(0, limit);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/products.ts\n");

